import os
import sys

matches = []
for root, dirs, files in os.walk("."):
    # Skip hidden/skill directories to keep the search focused
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    for f in files:
        if f.lower() == "report.pdf":
            matches.append(os.path.join(root, f))

print("Found report.pdf files:")
for m in matches:
    print(m)

if not matches:
    print("No report.pdf found.")

